//! Run from any directory; generated files always belong to this workspace.
use anyhow::Result;
use std::{fs, path::Path};
use ts_rs::{Config, TS};
use zapret_core::api::*;

fn main() -> Result<()> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    fs::create_dir_all(root.join("contracts"))?;
    fs::create_dir_all(root.join("ui/src/generated"))?;
    let schema = serde_json::to_string_pretty(&schemars::schema_for!(DaemonApi))?;
    fs::write(root.join("contracts/daemon-api.schema.json"), schema + "\n")?;
    let schema =
        serde_json::to_string_pretty(&schemars::schema_for!(zapret_core::bundle::BundleContract))?;
    fs::write(
        root.join("contracts/bundle-manifest.schema.json"),
        schema + "\n",
    )?;
    let schema =
        serde_json::to_string_pretty(&schemars::schema_for!(zapret_core::targets::TargetList))?;
    fs::write(root.join("contracts/targets.schema.json"), schema + "\n")?;
    let config = Config::default();
    let declarations = [
        DaemonCommand::decl(&config),
        DaemonResponse::decl(&config),
        ApiResponse::decl(&config),
        Strategy::decl(&config),
        Capabilities::decl(&config),
        SecureDns::decl(&config),
        ServiceStatus::decl(&config),
        ProbeResult::decl(&config),
        Operation::decl(&config),
        BundleStatus::decl(&config),
        Health::decl(&config),
        Snapshot::decl(&config),
        DoctorCheck::decl(&config),
        DoctorResult::decl(&config),
        Report::decl(&config),
        ReportCheck::decl(&config),
    ];
    let mut types =
        "// Generated by cargo run -p zapret-core --bin gen-contracts. Do not edit.\n".to_owned();
    for declaration in declarations {
        types.push_str("export ");
        types.push_str(&declaration);
        types.push('\n');
    }
    fs::write(root.join("ui/src/generated/api.ts"), types)?;
    Ok(())
}
